http {
    # Zona cache: 10 MB metadata (~80 ribu key), maks 1 GB file, hapus yang tak dipakai 60 menit
    proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=app_cache:10m max_size=1g inactive=60m use_temp_path=off;

    server {
        listen 80;
        server_name contoh.com;

        location / {
            proxy_cache app_cache;
            proxy_cache_valid 200 301 302 10m;
            proxy_cache_valid 404 1m;
            proxy_cache_use_stale error timeout updating http_500 http_502 http_503;
            proxy_pass http://127.0.0.1:8080;
            add_header X-Cache-Status $upstream_cache_status;
        }
    }
}

# Cache key kustom: bedakan berdasarkan bahasa dari header
proxy_cache_key '$scheme$request_method$host$request_uri$http_accept_language';

# Validitas berbeda per kode status
proxy_cache_valid 200 301 302 10m;
proxy_cache_valid 404 1m;
proxy_cache_valid any 0;

# Jangan simpan respons yang mengandung Set-Cookie (data sesi)
proxy_no_cache $cookie_session $http_authorization;
proxy_cache_bypass $cookie_session $http_authorization;

http {
    fastcgi_cache_path /var/cache/nginx/fastcgi levels=1:2 keys_zone=php_cache:10m max_size=1g inactive=60m use_temp_path=off;

    server {
        listen 80;
        server_name contoh.com;
        root /var/www/contoh.com;

        location ~ \.php$ {
            fastcgi_cache php_cache;
            fastcgi_cache_valid 200 10m;
            fastcgi_cache_use_stale error timeout updating;
            fastcgi_cache_bypass $cookie_session $http_authorization;
            fastcgi_no_cache $cookie_session $http_authorization;
            include fastcgi_params;
            fastcgi_pass unix:/run/php/php8.3-fpm.sock;
            add_header X-Cache-Status $upstream_cache_status;
        }
    }
}

# Lewati cache untuk pengguna login & admin
map $cookie_session $skip_cache {
    default 0;
    ~.+ 1;
}

server {
    location / {
        proxy_cache app_cache;
        proxy_cache_bypass $skip_cache $arg_nocache;
        proxy_no_cache $skip_cache $arg_nocache;
        proxy_pass http://127.0.0.1:8080;
    }
}
